rows9=[[c for c in range(W) if I[r,c]==9] for r in range(H)]
cols9=[[r for r in range(H) if I[r,c]==9] for c in range(W)]
def between(idx,i):
    return any(min(a,b)<i<max(a,b) for a,b in zip(idx,idx[1:]))
pred=[[0]*W for _ in range(H)]
for r in range(H):
    for c in range(W):
        if I[r,c]==1 and (between(rows9[r],c) or between(cols9[c],r)):
            pred[r][c]=3
print(np.array(pred)==O)
print('mismatch cells:',[(r,c,O[r,c],pred[r][c]) for r in range(H) for c in range(W) if pred[r][c]!=O[r,c]][:40])

def btw(idx,i,wrap):
    idx=sorted(idx)
    for a,b in zip(idx,idx[1:]):
        if a<i<b:return True
    if wrap and len(idx)>=2:
        a,b=idx[-1],idx[0]+(H if len(idx)<2 else 0)
        # wrap segment: from last to first around
        if i>idx[-1] or i<idx[0]: return True if len(idx)>=1 else False
        return False
    return False
def btw2(idx,i,wrap):
    idx=sorted(idx);n=len(idx)
    for a,b in zip(idx,idx[1:]):
        if a<i<b:return True
    if wrap and n>=2 and (i>idx[-1] or i<idx[0]):return True
    return False
for wrap in (False,True):
  for name,f in [('R',lambda r,c:btw2(rows9[r],c,wrap)),('C',lambda r,c:btw2(cols9[c],r,wrap))]:
    p=np.array([[3 if (I[r,c]==1 and f(r,c)) else 0 for c in range(W)] for r in range(H)])
    m=((p!=O)&(O==1)).sum()+((p==3)&(O!=3)).sum()
    print(wrap,name,'errors',m)
for wrap in (False,True):
  for comb,fn in [('OR',lambda a,b:a or b),('AND',lambda a,b:a and b)]:
    p=np.array([[3 if (I[r,c]==1 and fn(btw2(rows9[r],c,wrap),btw2(cols9[c],r,wrap))) else 0 for c in range(W)] for r in range(H)])
    err=[(r,c) for r in range(H) for c in range(W) if p[r,c]!=O[r,c] and I[r,c]==1]
    print(wrap,comb,'errors',len(err),err[:10])

def btw_nw(idx,i):
    idx=sorted(idx);return any(a<i<b for a,b in zip(idx,idx[1:]))
shadow=lambda r,c: btw_nw(rows9[r],c) or btw_nw(cols9[c],r)
# border-connected 1s (4-conn)
seen=np.zeros_like(I,bool);q=deque()
for r in range(H):
    for c in (0,W-1):
        if I[r,c]==1 and not seen[r,c]:seen[r,c]=1;q.append((r,c))
for c in range(W):
    for r in (0,H-1):
        if I[r,c]==1 and not seen[r,c]:seen[r,c]=1;q.append((r,c))
while q:
    y,x=q.popleft()
    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
        ny,nx=y+dy,x+dx
        if 0<=ny<H and 0<=nx<W and I[ny,nx]==1 and not seen[ny,nx]:
