p=np.array([[3 if (I[r,c]==1 and shadow(r,c) and not seen[r,c]) else (1 if I[r,c]==1 else I[r,c]) for c in range(W)] for r in range(H)])
print((p==O).all())
print([(r,c) for r in range(H) for c in range(W) if p[r,c]!=O[r,c]])
